def removeDuplicates(nums: list[int]) -> int:
    write = 0
    for read, value in enumerate(nums):
        # 只在写入后不会超过两次时保留当前值。
        if write < 2 or value != nums[write - 2]:
            nums[write] = value
            write += 1
    return write

code.cpp:
int removeDuplicates(vector<int>& nums) {
    int write = 0;
    for (int read = 0; read < static_cast<int>(nums.size()); ++read) {
        // 比较写入位置前两个元素，保证每个值至多保留两次。
        if (write < 2 || nums[read] != nums[write - 2]) {
            nums[write++] = nums[read];
        }
    }
    return write;
}
